const ADMIN_VIEW_BY_SECTION = Object.fromEntries(
  Object.entries(ADMIN_SECTION_BY_VIEW).map(([view, section]) => [section, view]),
);

const ADMIN_PROCESSING_SECTION_PREFIX = "processing-";
const ADMIN_MOUNTING_NODES_SECTION = "mounting-nodes";

function readAdminRouteFromLocation() {
  if (typeof window === "undefined") {
    return {
      hasSection: false,
      mountingNodesRoute: null,
      processingTab: null,
      view: null,
    };
  }

  const searchParams = new URLSearchParams(window.location.search);
  const section = String(searchParams.get("section") || "").trim();

  if (!section) {
    return {
      hasSection: false,
      mountingNodesRoute: null,
      processingTab: null,
      view: null,
    };
  }

  if (section === ADMIN_MOUNTING_NODES_SECTION) {
    const mountingNodesRoute = parseMountingNodesRoute(window.location.search);

    return {
      hasSection: true,
      mountingNodesRoute: mountingNodesRoute || normalizeMountingNodesRoute({ mode: "list", nodeId: null }),
      processingTab: null,
      view: "catalogHoles",
    };
  }

  if (
    [
      "connections-overview",
      "mounting-schemes",
      "connection-types",
      "mounting-compatibility",
      "connections-testing",
    ].includes(section)
  ) {
    return {
      hasSection: true,
      mountingNodesRoute: null,
      processingTab: null,
      view: ADMIN_VIEW_BY_SECTION[section],
    };
  }

  if (section.startsWith(ADMIN_PROCESSING_SECTION_PREFIX)) {
    return {
      hasSection: true,
      mountingNodesRoute: null,
      processingTab: section.slice(ADMIN_PROCESSING_SECTION_PREFIX.length) || "overview",
      view: "processing",
    };
  }

  const mappedView = ADMIN_VIEW_BY_SECTION[section];

  if (mappedView) {
    return {
      hasSection: true,
      mountingNodesRoute: null,
      processingTab: null,
      view: mappedView,
    };
  }

  return {
    hasSection: true,
    mountingNodesRoute: null,
    processingTab: null,
    view: "home",
  };
}

function buildAdminHistoryUrl(
  {
    mountingNodesRoute = null,
    processingTab = "overview",
    view = "home",
  } = {},
  currentHash = "",
) {
  if (typeof window === "undefined") {
    return "";
  }

  const params = new URLSearchParams();
  const normalizedView = normalizeCatalogView(view);

  if (normalizedView === "catalogHoles") {
    const normalizedRoute = normalizeMountingNodesRoute(
      mountingNodesRoute || { mode: "list", nodeId: null },
    );

    return `${window.location.pathname}${buildMountingNodesRouteUrl(normalizedRoute, window.location.search)}${currentHash || ""}`;
  } else if (
    [
      "connectionsOverview",
      "mountingSchemes",
      "connectionTypes",
      "mountingCompatibility",
      "connectionsTesting",
    ].includes(normalizedView)
  ) {
    params.set("section", ADMIN_SECTION_BY_VIEW[normalizedView] || "connections-overview");
  } else if (normalizedView === "processing") {
    const normalizedProcessingTab = normalizeProcessingWorkspaceTab(processingTab, {
      canUseFittingHoles: true,
      isAdmin: true,
    });

    params.set("section", `${ADMIN_PROCESSING_SECTION_PREFIX}${normalizedProcessingTab}`);
  } else {
    params.set("section", ADMIN_SECTION_BY_VIEW[normalizedView] || "home");
  }

  const queryString = params.toString();
  return `${window.location.pathname}${queryString ? `?${queryString}` : ""}${currentHash || ""}`;
}

function updateAdminHistory(route, { replace = false } = {}) {
  if (typeof window === "undefined") {
    return;
  }

  const nextUrl = buildAdminHistoryUrl(route, window.location.hash || "");
  const currentUrl = `${window.location.pathname}${window.location.search}${window.location.hash || ""}`;

  if (nextUrl === currentUrl) {
    return;
  }

  const historyMethod = replace ? window.history.replaceState : window.history.pushState;
  historyMethod.call(window.history, null, document.title, nextUrl);
}

function consumeAdminTokenHandoff() {
  const hashParams = new URLSearchParams(window.location.hash.replace(/^#/, ""));
  const searchParams = new URLSearchParams(window.location.search);
  const shouldLogout =
    hashParams.get(ADMIN_LOGOUT_HASH_KEY) === "1" ||
    searchParams.get(ADMIN_LOGOUT_HASH_KEY) === "1";
  const handoffToken = (
    hashParams.get(ADMIN_TOKEN_HASH_KEY) ||
    searchParams.get(ADMIN_TOKEN_HASH_KEY) ||
    ""
  ).trim();

  if (shouldLogout && !handoffToken) {
    localStorage.removeItem(TOKEN_STORAGE_KEY);
    localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, "home");
    localStorage.removeItem(ACTIVE_PROJECT_ID_STORAGE_KEY);
    localStorage.removeItem(ACTIVE_PROJECT_TAB_STORAGE_KEY);
  }

  if (!handoffToken) {
    hashParams.delete(ADMIN_LOGOUT_HASH_KEY);
    searchParams.delete(ADMIN_LOGOUT_HASH_KEY);

    const cleanHash = hashParams.toString();
    const cleanSearch = searchParams.toString();
    const nextUrl = `${window.location.pathname}${cleanSearch ? `?${cleanSearch}` : ""}${cleanHash ? `#${cleanHash}` : ""}`;
    window.history.replaceState({}, document.title, nextUrl);

    return localStorage.getItem(TOKEN_STORAGE_KEY) || "";
  }

  const previousToken = localStorage.getItem(TOKEN_STORAGE_KEY) || "";
  localStorage.setItem(TOKEN_STORAGE_KEY, handoffToken);

  if (handoffToken !== previousToken) {
    localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, "home");
    localStorage.removeItem(ACTIVE_PROJECT_ID_STORAGE_KEY);
    localStorage.removeItem(ACTIVE_PROJECT_TAB_STORAGE_KEY);
  }

  hashParams.delete(ADMIN_TOKEN_HASH_KEY);
  hashParams.delete(ADMIN_LOGOUT_HASH_KEY);
  searchParams.delete(ADMIN_TOKEN_HASH_KEY);
  searchParams.delete(ADMIN_LOGOUT_HASH_KEY);

  const nextSearch = searchParams.toString();
  const nextHash = hashParams.toString();
  const nextUrl = `${window.location.pathname}${nextSearch ? `?${nextSearch}` : ""}${nextHash ? `#${nextHash}` : ""}`;
  window.history.replaceState(null, document.title, nextUrl);

  return handoffToken;
}

function decodeAdminTokenPayload(token) {
  const rawToken = String(token || "").trim();

  if (!rawToken) {
    return null;
  }

  try {
    const [payloadPart] = rawToken.split(".");

    if (!payloadPart) {
      return null;
    }

    const normalizedPayload = payloadPart.replace(/-/g, "+").replace(/_/g, "/");
    const paddedPayload = normalizedPayload.padEnd(
      normalizedPayload.length + ((4 - (normalizedPayload.length % 4)) % 4),
      "=",
    );

    return JSON.parse(window.atob(paddedPayload));
  } catch {
    return null;
  }
}

function isAdminTokenExpired(token) {
  const payload = decodeAdminTokenPayload(token);
  const exp = Number(payload?.exp || 0);

  if (!exp) {
    return false;
  }

  return exp <= Math.floor(Date.now() / 1000);
}

function readPersistedAdminToken() {
  const token = consumeAdminTokenHandoff();

  if (!token) {
    return "";
  }

  if (!isAdminTokenExpired(token)) {
    return token;
  }

  localStorage.removeItem(TOKEN_STORAGE_KEY);
  localStorage.removeItem(USER_STORAGE_KEY);
  return "";
}

function readPersistedAdminUser(token) {
  if (!token) {
    return null;
  }

  try {
    const rawValue = localStorage.getItem(USER_STORAGE_KEY);

    if (!rawValue) {
      return null;
    }

    const parsedUser = JSON.parse(rawValue);

    if (!parsedUser || typeof parsedUser !== "object") {
      return null;
    }

    return parsedUser;
  } catch {
    return null;
  }
}
