function parseCommaSeparatedNumbers(value) {
  return String(value || "")
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean)
    .map((item) => Number(item))
    .filter((item) => Number.isFinite(item));
}

function formatCommaSeparatedNumbers(value) {
  if (!Array.isArray(value) || !value.length) {
    return "";
  }

  return value
    .map((item) => Number(item))
    .filter((item) => Number.isFinite(item))
    .join(", ");
}

