function updateServiceTreeNode(nodes, itemId, updater) {
  return nodes.map((node) => {
    if (node.id === itemId) {
      return updater(node);
    }

    if (node.children?.length) {
      return {
        ...node,
        children: updateServiceTreeNode(node.children, itemId, updater),
      };
    }

    return node;
  });
}

function getViyarServiceDescriptionStatus(node, t) {
  const fullDescription = String(node?.full_description || "").trim();
  const hasFullDescription = Boolean(fullDescription);
  const hasShortDescription = Boolean(String(node?.description || "").trim());
  const parseStatus = String(node?.rules_parse_status || "").trim().toLowerCase();
  const fullDescriptionLower = fullDescription.toLowerCase();
  const characteristicsOnly =
    fullDescription &&
    (
      fullDescriptionLower.includes("основні характеристики продукту") ||
      fullDescriptionLower.includes("технічні характеристики та функціональність")
    ) &&
    !(
      fullDescriptionLower.includes("опис") ||
      fullDescriptionLower.includes("обмеження") ||
      fullDescriptionLower.includes("обладнання")
    );
  const staleServiceText =
    fullDescription &&
    !(
      fullDescriptionLower.includes("опис") &&
      (fullDescriptionLower.includes("обмеження") ||
        fullDescriptionLower.includes("обладнання"))
    ) &&
    (
      fullDescriptionLower.includes("код:") ||
      fullDescriptionLower.includes("ціна viyarpro") ||
      fullDescriptionLower.includes("строки") ||
      fullDescriptionLower.includes("увага! колір товару") ||
      fullDescriptionLower.includes("грн/шт") ||
      fullDescriptionLower.includes("є/шт")
    );

  if (parseStatus === "needs_review" || characteristicsOnly || staleServiceText) {
    return { className: "warning", label: t.viyarDescriptionStatusReview };
  }

  if (hasFullDescription) {
    return { className: "success", label: t.viyarDescriptionStatusFull };
  }

  if (hasShortDescription) {
    return { className: "subtle", label: t.viyarDescriptionStatusShort };
  }

  return { className: "muted", label: t.viyarDescriptionStatusEmpty };
}

function ServiceCatalogTreeNode({
  collapsedFolders,
  level = 0,
  mutationLoading = false,
  node,
  loading = false,
  onSaveService,
  onServiceFieldChange,
  onToggleCollapse,
  searchQuery,
  t,
}) {
  const [isDescriptionOpen, setIsDescriptionOpen] = useState(false);
  const isFolder = node.item_type === "folder";
  const serviceDescription = isFolder ? node.description : (node.full_description || node.description);
  const isCollapsed =
    isFolder &&
    !searchQuery.trim() &&
    Boolean(collapsedFolders[node.external_code]);
  const effectiveStatus = node.user_price_sync_status || node.price_sync_status;
  const effectiveSourceLabel =
    node.user_price_source_label || node.price_source_label;
  const hasVisiblePrice =
    node.user_price !== null &&
    node.user_price !== undefined;
  const descriptionStatus = getViyarServiceDescriptionStatus(node, t);
  const nestedServiceCount = isFolder
    ? countServiceTreeItems(node.children || [])
    : 0;
  const rowPaddingLeft = isFolder
    ? `${level * 18}px`
    : `${Math.max(0, (level - 1) * 18)}px`;

  return (
    <li className={`service-tree-node ${isFolder ? "folder" : "service"}`}>
      <div
        data-folder-code={isFolder ? node.external_code : undefined}
        className={`service-tree-row${!isFolder ? " service-row" : ""}`}
        style={{ paddingLeft: rowPaddingLeft }}
      >
        {isFolder ? (
          <>
            <div className="service-tree-main">
              <button
                className="service-tree-collapse"
                onClick={() => onToggleCollapse(node.external_code)}
                type="button"
              >
                <ChevronRight
                  className={isCollapsed ? "" : "expanded"}
                  size={14}
                />
              </button>
              <span className={`service-tree-bullet ${isFolder ? "folder" : "service"}`} />
              <div className="service-tree-copy">
                <div className="service-tree-title-row">
                  <strong>{node.name}</strong>
                  {nestedServiceCount ? (
                    <span className="service-tree-folder-count">
                      {nestedServiceCount}
                    </span>
                  ) : null}
                </div>
                {node.description && isDescriptionOpen ? <span>{node.description}</span> : null}
              </div>
            </div>
            <div className="service-tree-meta">
              {node.description ? (
                <button
                  className="ghost-button compact-button service-tree-folder-action"
                  onClick={() => setIsDescriptionOpen((current) => !current)}
                  type="button"
                >
                  {isDescriptionOpen ? t.hideDescription : t.showDescription}
                </button>
              ) : null}
              <div className="service-tree-folder-meta">
                <span className="service-tree-badge subtle">{t.folder}</span>
              </div>
            </div>
          </>
        ) : (
          <div className="service-tree-service-line">
            <div className="service-tree-name-cell">
              <span className="service-tree-bullet service" />
              <div className="service-tree-name-stack">
                <strong>{node.name}</strong>
                <span className={`service-tree-badge service-tree-status-badge ${descriptionStatus.className}`}>
                  {descriptionStatus.label}
                </span>
              </div>
            </div>
            <label>
              <span>{t.viyarArticle}</span>
              <input
                disabled
                type="text"
                value={node.article || ""}
              />
            </label>
            <label>
              <span>{t.serviceUnit}</span>
              <input
                disabled={mutationLoading}
                onChange={(event) =>
                  onServiceFieldChange(node.id, "unit", event.target.value)
                }
                type="text"
                value={node.unit || ""}
              />
            </label>
            <label>
              <span>{t.basePrice}</span>
              <input
                disabled={mutationLoading}
                min="0"
                onChange={(event) =>
                  onServiceFieldChange(node.id, "base_price", event.target.value)
                }
                step="0.01"
                type="number"
                value={node.base_price ?? ""}
              />
            </label>
            <button
              className="ghost-button compact-button service-tree-inline-action"
              disabled={!serviceDescription}
              onClick={() => setIsDescriptionOpen((current) => !current)}
              type="button"
            >
              {isDescriptionOpen ? t.hideDescription : t.showDescription}
            </button>
            <label className="toggle-label">
              <input
                checked={Boolean(node.is_calculable)}
                disabled={mutationLoading}
                onChange={(event) =>
                  onServiceFieldChange(node.id, "is_calculable", event.target.checked)
                }
                type="checkbox"
              />
              {t.viyarCalculable}
            </label>
            <label className="toggle-label">
              <input
                checked={Boolean(node.is_active)}
                disabled={mutationLoading}
                onChange={(event) =>
                  onServiceFieldChange(node.id, "is_active", event.target.checked)
                }
                type="checkbox"
              />
              {t.enabled}
            </label>
            <button
              className="ghost-button compact-button"
              disabled={mutationLoading}
              onClick={() => onSaveService(node)}
              type="button"
            >
              <Save size={16} />
              {t.save}
            </button>
          </div>
        )}
      </div>
      {serviceDescription && isDescriptionOpen ? (
        <div
          className={`service-tree-description-panel${isFolder ? " folder-description-panel" : ""}`}
          style={{ marginLeft: `${Math.max(0, (level - 1) * 18) + (isFolder ? 18 : 32)}px` }}
        >
          <strong>{t.showDescription}</strong>
          <p>{serviceDescription}</p>
        </div>
      ) : null}
      {node.children?.length && !isCollapsed ? (
        <ul className="service-tree-list">
          {node.children.map((child) => (
            <ServiceCatalogTreeNode
              collapsedFolders={collapsedFolders}
              key={child.external_code}
              level={level + 1}
              loading={loading}
              mutationLoading={mutationLoading}
              node={child}
              onSaveService={onSaveService}
              onServiceFieldChange={onServiceFieldChange}
              onToggleCollapse={onToggleCollapse}
              searchQuery={searchQuery}
              t={t}
            />
          ))}
        </ul>
      ) : null}
    </li>
  );
}

