  function changeLanguage(nextLanguage) {
    localStorage.setItem(LANGUAGE_STORAGE_KEY, nextLanguage);
    setLanguage(nextLanguage);
  }

  async function loadUser(activeToken) {
    const result = await getCurrentUser(activeToken);

    if (tokenRef.current !== activeToken) {
      return null;
    }

    if (!result.success) {
      if (result.status === 401 || result.status === 403) {
        localStorage.removeItem(TOKEN_STORAGE_KEY);
        localStorage.removeItem(USER_STORAGE_KEY);
        setToken("");
        setUser(null);
        return null;
      }

      setStatus({ message: result.error || t.loginFailed, tone: "error" });
      return user || readPersistedAdminUser(activeToken);
    }

    setUser(result.user);
    return result.user;
  }

  async function loadProjects(
    activeToken = token,
    nextOffset = offset,
    filters = appliedProjectFilters,
    viewer = user,
  ) {
    if (!activeToken) {
      return;
    }

    if (!canViewProjects(viewer)) {
      const fallbackView = canCreateProjects(viewer) ? "createProject" : "home";
      setActiveView(fallbackView);
      activeViewRef.current = fallbackView;
      localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, fallbackView);
      setStatus({ message: t.projectViewRestricted, tone: "info" });
      return;
    }

    setLoading(true);
    const requestFilters = {
      ...filters,
    };

    if (viewer?.role !== "admin") {
      delete requestFilters.ownership_scope;
    }

    const result = await listProjects(
      activeToken,
      PAGE_SIZE,
      nextOffset,
      requestFilters,
    );
    setLoading(false);

    if (!result.success) {
      setStatus(result.error || t.unableToLoadProjects);
      return;
    }

    setProjects(result.projects);
    setTotal(result.total);
    setOffset(result.offset);
  }

  async function loadProjectQuota(activeToken = token, viewer = user) {
    if (!activeToken || !canCreateProjects(viewer)) {
      setProjectOwnershipQuota(null);
      setProjectOwnershipQuotaError("");
      setProjectOwnershipQuotaLoaded(false);
      setProjectOwnershipQuotaLoading(false);
      return null;
    }

    setProjectOwnershipQuotaLoading(true);
    setProjectOwnershipQuotaError("");

    const result = await getProjectQuota(activeToken);
    setProjectOwnershipQuotaLoading(false);

    if (!result.success) {
      setProjectOwnershipQuota(null);
      setProjectOwnershipQuotaError(result.error || t.unableToLoadProjects);
      setProjectOwnershipQuotaLoaded(true);
      return null;
    }

    const quota = result.project_quota || result.quota || result;
    setProjectOwnershipQuota(quota);
    setProjectOwnershipQuotaLoaded(true);
    return quota;
  }

  useEffect(() => {
    if (!token) {
      return;
    }

    if (activeView !== "projects" && activeView !== "createProject") {
      return;
    }

    loadProjectQuota(token, user);
  }, [activeView, token, user?.entitlements, user?.id, user?.role]);

  async function loadSpecificationCatalog() {
    const result = await getSpecificationCatalog();

    if (!result.success) {
      return;
    }

    setSpecificationCatalog({
      project_types: normalizeProjectTypes(result.project_types),
      slide_types: result.slide_types || DEFAULT_SPECIFICATION_CATALOG.slide_types,
      bottom_types: result.bottom_types || DEFAULT_SPECIFICATION_CATALOG.bottom_types,
      material_thicknesses:
        result.material_thicknesses ||
        DEFAULT_SPECIFICATION_CATALOG.material_thicknesses,
      edge_bandings: result.edge_bandings || DEFAULT_SPECIFICATION_CATALOG.edge_bandings,
      handle_positions:
        result.handle_positions || DEFAULT_SPECIFICATION_CATALOG.handle_positions,
    });
  }

