  async function handlePreviewCuttingPart(partCode) {
    setSelectedCuttingPartCode(partCode);
    setStatus("");

    if (!selectedProjectId || !partCode) {
      return;
    }

    const result = await getProjectPartDetail(token, selectedProjectId, partCode);

    if (!result.success) {
      return;
    }

    setSelectedPartDetail(result);
    setSelectedEdgeSide(null);
  }

  async function handleSelectCuttingPart(partCode = selectedCuttingPartCode) {
    if (!selectedProjectId) {
      return;
    }

    if (!partCode) {
      return;
    }

    const result = await getProjectPartDetail(token, selectedProjectId, partCode);

    if (!result.success) {
      setStatus(result.error || t.unableToLoadPart);
      return;
    }

    setSelectedCuttingPartCode(partCode);
    setSelectedPartDetail(result);
    setSelectedEdgeSide(null);
    setActiveProjectTab("partDetail");
    setStatus("");
  }

  function handleClearCuttingPartSelection() {
    setSelectedCuttingPartCode(null);
    setHoveredCuttingPartCode(null);
    setStatus("");
  }

  function handlePartEdgeChange(side, value) {
    setSelectedPartDetail((current) => {
      if (!current?.part) {
        return current;
      }

      return {
        ...current,
        part: {
          ...current.part,
          [`edge_${side}`]: value || null,
        },
      };
    });
  }

  async function handleSavePartEdges() {
    if (!selectedProjectId || !selectedPartDetail?.part) {
      return;
    }

    setLoading(true);
    const result = await updateProjectPartEdges(
      token,
      selectedProjectId,
      selectedPartDetail.part.export_code,
      {
        top: selectedPartDetail.part.edge_top || null,
        bottom: selectedPartDetail.part.edge_bottom || null,
        left: selectedPartDetail.part.edge_left || null,
        right: selectedPartDetail.part.edge_right || null,
      },
    );
    setLoading(false);

    if (!result.success) {
      setStatus(result.error || t.unableToSaveEdges);
      return;
    }

    setSelectedPartDetail(result);
    await loadProjectProduction(selectedProjectId, false);
    setStatus(t.edgeSaved);
  }

  function createMachiningRow(kind) {
    const nextNumber = (selectedPartDetail?.[kind]?.length || 0) + 1;

    if (kind === "holes") {
      return {
        number: nextNumber,
        side: "front",
        origin: "left_bottom",
        x: 0,
        y: 0,
        z: 0,
        diameter: 5,
        depth: selectedPartDetail?.part?.thickness || 18,
        type: "manual",
      };
    }

    if (kind === "grooves") {
      return {
        number: nextNumber,
        side: "front",
        origin: "left_bottom",
        x: 0,
        y: 0,
        depth: 8,
        width: 4,
        length: selectedPartDetail?.part?.width || 0,
        type: "manual",
      };
    }

    return {
      number: nextNumber,
      side: "bottom",
      origin: "left_bottom",
      x: 0,
      y: 0,
      depth: 2,
      width: 12,
      length: selectedPartDetail?.part?.width || 0,
      radius: 0,
      type: "manual",
    };
  }

  function handleAddMachiningRow(kind) {
    setSelectedPartDetail((current) => ({
      ...current,
      [kind]: [
        ...(current?.[kind] || []),
        createMachiningRow(kind),
      ],
    }));
  }

  function handleMachiningChange(kind, index, field, value) {
    setSelectedPartDetail((current) => ({
      ...current,
      [kind]: (current?.[kind] || []).map((row, rowIndex) => (
        rowIndex === index
          ? {
              ...row,
              [field]: ["side", "origin", "type"].includes(field) ? value : Number(value),
            }
          : row
      )),
    }));
  }

  function handleRemoveMachiningRow(kind, index) {
    setSelectedPartDetail((current) => ({
      ...current,
      [kind]: (current?.[kind] || [])
        .filter((_, rowIndex) => rowIndex !== index)
        .map((row, rowIndex) => ({
          ...row,
          number: rowIndex + 1,
        })),
    }));
  }

  async function handleSavePartMachining() {
    if (!selectedProjectId || !selectedPartDetail?.part) {
      return;
    }

    setLoading(true);
    const result = await updateProjectPartMachining(
      token,
      selectedProjectId,
      selectedPartDetail.part.export_code,
      {
        holes: selectedPartDetail.holes || [],
        grooves: selectedPartDetail.grooves || [],
        quarters: selectedPartDetail.quarters || [],
      },
    );
    setLoading(false);

    if (!result.success) {
      setStatus(result.error || t.unableToSaveMachining);
      return;
    }

    setSelectedPartDetail(result);
    setStatus(t.machiningSaved);
  }

  async function switchView(view, viewer = user, openContext = null) {
    const nextView = normalizeCatalogView(view === "catalog" ? "catalogViyar" : view);
    const skipHistoryUpdate = Boolean(openContext?.skipHistoryUpdate);
    let nextProcessingTab = activeProcessingTab;
    let nextMountingNodesRoute = null;

    if ((nextView === "catalogFittings" || nextView === "catalogFasteners") && !canViewFittingCatalog) {
      return;
    }

    if (CATALOG_FITTING_TAXONOMY_VIEWS.has(nextView) && viewer?.role !== "admin") {
      const fallbackView = canViewMaterialCatalog ? "catalogMaterials" : "home";
      setActiveView(fallbackView);
      activeViewRef.current = fallbackView;
      localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, fallbackView);
      return;
    }

    if ((nextView === "catalogHoles" || nextView === "catalogBundles") && !canViewFittingHoles) {
      const fallbackView = canViewMaterialCatalog ? "catalogMaterials" : "home";
      setActiveView(fallbackView);
      activeViewRef.current = fallbackView;
      localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, fallbackView);
      setStatus({
        message: language === "uk"
          ? "Розділ присадки фурнітури недоступний у вашому тарифі."
          : "The fitting holes section is unavailable for your plan.",
        tone: "error",
      });
      return;
    }

    if (nextView === "processing" && !canAccessProcessingWorkspace) {
      const fallbackView = canViewMaterialCatalog ? "catalogMaterials" : "home";
      setActiveView(fallbackView);
      activeViewRef.current = fallbackView;
      localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, fallbackView);
      setStatus({
        message: language === "uk"
          ? "Розділ обробки деталей недоступний у вашому тарифі."
          : "The processing workspace is unavailable for your plan.",
        tone: "error",
      });
      return;
    }

    if (
      activeView === "entitlements" &&
      entitlementsHasUnsavedChanges &&
      nextView !== "entitlements" &&
      !window.confirm(
        language === "uk"
          ? "У тарифній матриці є незбережені зміни. Залишити сторінку?"
          : "There are unsaved changes in the entitlements matrix. Leave this page?",
      )
    ) {
      return;
    }

    if (nextView === "processing") {
      setIsProcessingMenuOpen(true);
    }

    if (shouldAutoOpenConnectionsMenu(nextView)) {
      setIsConnectionsMenuOpen(true);
    }

    if (nextView === "processing" && openContext?.processingTab) {
      const normalizedProcessingTab = normalizeProcessingWorkspaceTab(openContext.processingTab, {
        canUseFittingHoles: canViewFittingHoles,
        isAdmin: viewer?.role === "admin",
      });
      nextProcessingTab = normalizedProcessingTab;
      setActiveProcessingTab(normalizedProcessingTab);
      localStorage.setItem(PROCESSING_WORKSPACE_STORAGE_KEY, normalizedProcessingTab);
    }

    if (nextView !== "catalogHoles") {
      setCatalogHolesMode("list");
      setCatalogHolesOpenContext(null);
      setCatalogHolesReturnState(null);
      setCatalogHolesDetailOpen(false);
      setCatalogHolesBreadcrumbNodeId(null);
      setCatalogHolesBreadcrumbNodeName("");
      setCatalogHolesSaving(false);
      setMountingNodesRouteState(null);
      setMountingNodesInitialState(null);
      setMountingNodesRouteReady(true);
      setMountingNodesRouteLoadingMessage("");
      setMountingNodesRouteError("");
      mountingNodesEditorRestoreKeyRef.current = "";
      mountingNodesEditorRestorePromiseRef.current = null;
    }

    if (nextView === "catalogHoles") {
      const contextMountingNodeId = String(openContext?.mountingNodeId || "").trim();
      const baseContextNodeName = String(openContext?.nodeName || "").trim();
      const contextNodeCode = String(openContext?.nodeCode || "").trim();
      const contextFittingId = String(openContext?.fittingId || "").trim();
      const contextTemplateId = String(openContext?.templateId || "").trim();
      const contextVariantKey = normalizeHoleWorkspaceMountingVariantKey(openContext?.mountingVariantKey || "");
      const contextNodeDetail =
        openContext?.nodeDetail && typeof openContext.nodeDetail === "object" ? openContext.nodeDetail : null;
      const contextCategoryCode = resolveMountingNodesCategoryCode(
        openContext?.category_code,
        contextNodeDetail?.category_code ?? mountingNodesRouteState?.categoryCode,
      );
      const contextFunctionalCode = normalizeMountingNodeFunctionalCode(
        openContext?.functional_code ??
          contextNodeDetail?.functional_code ??
          mountingNodeEditorFunctionalCodeRef.current ??
          mountingNodeEditorDraft?.functional_code,
      ) || null;
      const contextNodeName = String(
        baseContextNodeName ||
          contextNodeDetail?.name ||
          catalogHolesReturnState?.selectedNodeDetail?.name ||
          catalogHolesReturnState?.selectedNode?.name ||
          catalogHolesBreadcrumbNodeName ||
          "",
      ).trim();

      if (contextMountingNodeId) {
        setCatalogHolesBreadcrumbNodeId(contextMountingNodeId);
        setCatalogHolesBreadcrumbNodeName(contextNodeName);
      } else {
        setCatalogHolesBreadcrumbNodeId(null);
        setCatalogHolesBreadcrumbNodeName("");
      }

      setCatalogHolesOpenContext(
        contextMountingNodeId
          ? {
            mountingNodeId: contextMountingNodeId,
            nodeCode: contextNodeCode,
            nodeName: contextNodeName,
            fittingId: contextFittingId,
            templateId: contextTemplateId || editorTemplateId,
            mountingVariantKey: contextVariantKey,
            category_code: contextCategoryCode,
            functional_code: contextFunctionalCode,
            nodeDetail: contextNodeDetail,
          }
          : null,
      );
      if (!contextMountingNodeId) {
        setCatalogHolesReturnState(null);
      }

      const nextCatalogHolesMode = contextMountingNodeId ? "editor" : "categories";
      nextMountingNodesRoute = normalizeMountingNodesRoute(
        contextMountingNodeId
          ? { mode: "editor", nodeId: contextMountingNodeId }
          : { mode: "categories", nodeId: null },
      );
      setMountingNodesRouteState(nextMountingNodesRoute);
      setCatalogHolesDetailOpen(false);
      setCatalogHolesMode(nextCatalogHolesMode);

      setIsProcessingMenuOpen(true);
    }

    setActiveView(nextView);
    activeViewRef.current = nextView;
    setStatus("");

    if (!skipHistoryUpdate) {
      updateAdminHistory({
        mountingNodesRoute: nextMountingNodesRoute,
        processingTab: nextProcessingTab,
        view: nextView,
      });
    }

    if (nextView !== "catalogMaterials") {
      materialDetailsRequestRef.current.open = false;
      setSelectedMaterialDetail(null);
      setMaterialDetailLoading(false);
    }

    if (nextView !== "catalogFittings" && nextView !== "catalogFasteners") {
      fittingDetailsRequestRef.current.open = false;
      fittingDetailsReturnFocusRef.current = null;
      setSelectedFittingDetail(null);
      setFittingDetailLoading(false);
      setFittingDetailError("");
    }

    if (nextView !== "catalogBundles") {
      bundleDetailsRequestRef.current.open = false;
      setHoleBundleDetailsOpen(false);
      setHoleBundleDetailsLoading(false);
      setHoleBundleDetails(null);
    }

    if (nextView !== "catalogFittings") {
      setOpenFittingMenuId("");
      closeFittingFormModal();
    }

    if (nextView === "home") {
      await loadHomeView(token, viewer);
      return;
    }

    if (nextView === "projects") {
      await loadProjects(token, offset, appliedProjectFilters, viewer);
      return;
    }

    if (nextView === "createProject") {
      if (!canCreateProjects(viewer)) {
        const fallbackView = canViewProjects(viewer) ? "projects" : "home";
        setActiveView(fallbackView);
        activeViewRef.current = fallbackView;
        localStorage.setItem(ACTIVE_VIEW_STORAGE_KEY, fallbackView);
        setStatus({ message: t.projectCreateRestricted, tone: "info" });
        return;
      }
      return;
    }

    if (nextView === "users") {
      await loadUsers(token, usersOffset, viewer);
      await loadUserChangeRequests(token, viewer);
      return;
    }

    if (nextView === "catalogValues") {
      await loadCatalogItems(token, viewer);
      return;
    }

    if (nextView === "catalogHub") {
      await loadCatalogView(token, viewer);
      return;
    }

    if (nextView === "catalogMaterials") {
      return;
    }

    if (nextView === "catalogFittings") {
      return;
    }

    if (nextView === "catalogHoles") {
      await loadFittingsCatalog(token, { search: "" });
      const contextMountingNodeId = String(openContext?.mountingNodeId || "").trim();
      const contextNodeDetail =
        openContext?.nodeDetail && typeof openContext.nodeDetail === "object" ? openContext.nodeDetail : null;
      const shouldPreserveEditorWorkspace = shouldPreserveMountingNodeEditorWorkspace(
        { mode: contextMountingNodeId ? "editor" : "list", nodeId: contextMountingNodeId || null },
        openContext,
      );

      if (!shouldPreserveEditorWorkspace) {
      setHoleWorkspaceMode("new");
      setHoleActiveBundleKey("");
      setHoleActiveBundleName("");
      setHoleActiveBundleMountingVariantKey("");
      setHoleBundleMountingVariantSaving(false);
      setHoleBundleName("");
      setHoleBundleCategoryCode("");
      setHoleBundleSelectedItemIds([]);
      setHoleBundleDraftItemIds([]);
      setSelectedHoleMountingVariantKey("surface_mount");
      setHoleSelectedFittingCategory("");
      setHoleSelectedFittingId("");
      setHoleSelectedTemplateId("");
      setHoleSelectedTemplate(null);
      setHoleTemplateItems([]);
      setHolePoints([]);
      setSelectedHolePointId("");
      closeHoleTemplateCreateForm();
      closeHolePointCreateForm();
      closeHolePointEditForm();
      }

      const contextFittingId = String(openContext?.fittingId || "").trim();
      const contextTemplateId = String(openContext?.templateId || "").trim();
      const contextVariantKey = normalizeHoleWorkspaceMountingVariantKey(openContext?.mountingVariantKey || "");
      let editorTemplateId = contextTemplateId;

      if (contextMountingNodeId && contextNodeDetail) {
        const editorContext = resolveMountingNodeEditorContext(contextNodeDetail, contextMountingNodeId);
        const editorTemplates = Array.isArray(editorContext?.nodeDetail?.templates)
          ? editorContext.nodeDetail.templates
          : [];
        editorTemplateId = String(contextTemplateId || editorContext?.templateId || "").trim();
        const editorTemplateLink =
          editorTemplates.find(
            (link) =>
              String(link?.template_id || link?.template?.id || link?.fitting_hole_template?.id || "") ===
              editorTemplateId,
          ) ||
          editorTemplates.find((link) => Boolean(link?.is_default)) ||
          editorTemplates[0] ||
          null;
        const editorTemplate =
          editorTemplateLink?.template && typeof editorTemplateLink.template === "object"
            ? editorTemplateLink.template
            : editorTemplateLink?.fitting_hole_template && typeof editorTemplateLink.fitting_hole_template === "object"
              ? editorTemplateLink.fitting_hole_template
              : null;
        const editorPoints = cloneMountingNodeEditorPoints(
          Array.isArray(editorTemplate?.points)
            ? editorTemplate.points
            : Array.isArray(editorContext?.points)
              ? editorContext.points
              : [],
        );

        setHoleWorkspaceMode("existing");
        setSelectedHoleMountingVariantKey(contextVariantKey || editorContext?.mountingVariantKey || "surface_mount");
        setHoleSelectedFittingId(
          String(editorContext?.fittingId || contextFittingId || editorTemplate?.fitting_id || "").trim(),
        );
        setHoleSelectedTemplateId(editorTemplateId);
        setHoleSelectedTemplate(editorTemplateLink ? cloneMountingNodeEditorDraft(editorTemplateLink) : null);
        setHoleTemplateItems(
          editorTemplates.map((link) => cloneMountingNodeEditorDraft(link)).filter(Boolean),
        );
        setHolePoints(editorPoints);
        setSelectedHolePointId("");
        setHoveredHolePointId("");
        setHoleTemplateDetailsLoaded(true);
        setHoleServicePreview(null);
        setHoleServicePreviewError("");
        setHoleServicePreviewLoading(false);
        setMountingNodeEditorHasChanges(false);
        return;
      }

      if (contextFittingId && contextTemplateId) {
        setHoleWorkspaceMode("existing");
        setSelectedHoleMountingVariantKey(contextVariantKey || "surface_mount");
        await handleHoleFittingChange(
          contextFittingId,
          contextTemplateId,
          "existing",
          contextVariantKey || "surface_mount",
        );
      }

      return;
    }

    if (nextView === "catalogBundles") {
      return;
    }

    if (nextView === "catalogServiceRules") {
      await loadFittingHoleServiceRules(token, viewer);
      return;
    }

    if (nextView === "catalogDrillingRules") {
      return;
    }

    if (nextView === "catalogViyar") {
      await loadViyarServices(token, viewer);
      return;
    }

    if (nextView === "catalogManual") {
      await loadManualServices(token, viewer);
      return;
    }

    if (nextView === "settings") {
      await loadSettingsView(token);
      return;
    }

    if (nextView === "audit") {
      await loadAuditLogs(token, auditOffset, viewer);
      return;
    }

    if (nextView === "entitlements") {
      return;
    }
  }

